(()=>{
'use strict';
const species={water:{name:'Water',formula:'H₂O',center:'O',radius:26,h:[-52,52],lp:[135,225]},ammonia:{name:'Ammonia',formula:'NH₃',center:'N',radius:25,h:[-55,0,55],lp:[180]},hf:{name:'Hydrogen fluoride',formula:'HF',center:'F',radius:24,h:[0],lp:[90,180,270]},hcl:{name:'Hydrogen chloride',formula:'HCl',center:'Cl',radius:29,h:[0],lp:[]}};
const gases={ne:{name:'Neon',symbol:'Ne',radius:32,scale:.6},ar:{name:'Argon',symbol:'Ar',radius:43,scale:1.5},xe:{name:'Xenon',symbol:'Xe',radius:55,scale:2.8}};
const rad=d=>d*Math.PI/180,clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
class Attractions{
 constructor(){this.mode='london';this.gas='ar';this.species='water';this.reset();}
 reset(){this.gap=220;this.angles=[this.mode==='hydrogen'&&this.species==='water'?-52:0,0];}
 get molecule(){return species[this.mode==='dipole'?'hcl':this.species];}
 setMode(mode){if(!['london','dipole','hydrogen'].includes(mode))return;this.mode=mode;this.reset();}
 setGap(gap){this.gap=clamp(gap,70,440);}
 rotate(side,angle){this.angles[side]=clamp(angle,-180,180);}
 geometry(){const m=this.molecule;return [0,1].map(i=>{const center={x:410+(i?1:-1)*this.gap/2,y:230,r:this.mode==='london'?gases[this.gas].radius:m.radius,symbol:this.mode==='london'?gases[this.gas].symbol:m.center};const angle=this.angles[i];return {center,angle,hydrogens:this.mode==='london'?[]:m.h.map(a=>({x:center.x+65*Math.cos(rad(a+angle)),y:center.y+65*Math.sin(rad(a+angle)),r:14,symbol:'H'})),lp:this.mode==='london'?[]:m.lp.map(a=>rad(a+angle))};});}
 interactions(){const groups=this.geometry(),g=this.gap,cloud=this.mode==='london'?gases[this.gas].scale:1.2;const dispersion=Math.min(1.5,.26*cloud*(170/g)**7);const orient=(3*Math.cos(rad(this.angles[0]))*Math.cos(rad(this.angles[1]))-Math.cos(rad(this.angles[0]-this.angles[1])))/2;const dipole=this.mode==='london'?0:clamp(.5*orient*(200/g)**4,-1.6,1.6);const hydrogen=[];
if(this.mode==='hydrogen')for(let i=0;i<2;i++){const donor=groups[i],acceptor=groups[1-i];for(const h of donor.hydrogens){const vx=acceptor.center.x-h.x,vy=acceptor.center.y-h.y,d=Math.hypot(vx,vy),hx=h.x-donor.center.x,hy=h.y-donor.center.y;const alignment=(hx*vx+hy*vy)/(65*d);const lpAlignment=Math.max(...acceptor.lp.map(a=>(Math.cos(a)*(h.x-acceptor.center.x)+Math.sin(a)*(h.y-acceptor.center.y))/d));if(d>36&&d<185&&alignment>.88&&lpAlignment>.55)hydrogen.push({from:h,to:acceptor.center,strength:clamp((185-d)/110,0,1)*alignment*lpAlignment});}}
let contact=0;for(const a of [groups[0].center,...groups[0].hydrogens])for(const b of [groups[1].center,...groups[1].hydrogens]){const gap=Math.hypot(a.x-b.x,a.y-b.y),limit=a.r+b.r+14;contact=Math.max(contact,(limit-gap)/limit);}
const repulsion=contact>0?2+8*contact:0,total=clamp(dispersion+dipole+hydrogen.reduce((s,h)=>s+1.4*h.strength,0)-repulsion,-1,1);
return {groups,dispersion,dipole,hydrogen,repulsion,total};}
}
if(typeof module!=='undefined'&&module.exports)module.exports={Attractions,species,gases};if(typeof document==='undefined')return;
const $=id=>document.getElementById('im-'+id);if(!$('game'))return;const game=new Attractions();let paused=false,time=.8,last=0,drag=null;
const dotPair=(x,y,a)=>[-1,1].map(s=>`<circle cx="${x+s*4*Math.cos(a)}" cy="${y+s*4*Math.sin(a)}" r="2.7" fill="#436d90"/>`).join('');
function renderDiagram(){const r=game.interactions(),m=game.molecule,fluctuation=Math.sin(time*1.2)*.7+Math.sin(time*2.7)*.3;let s='<title>Two particles and their intermolecular attractions</title><defs><radialGradient id="im-cloud"><stop offset="0" stop-color="#b5cbdc" stop-opacity=".25"/><stop offset=".7" stop-color="#92b9cf" stop-opacity=".28"/><stop offset="1" stop-color="#92b9cf" stop-opacity="0"/></radialGradient></defs>';
for(const [i,group] of r.groups.entries()){const c=group.center,shift=fluctuation*(game.mode==='london'?gases[game.gas].radius*.28:5)*(i?.8:1),size=game.mode==='london'?c.r*1.8:88;s+=`<g data-particle="${i}" class="im-particle" role="button" tabindex="0" aria-label="${i?'Right':'Left'} particle. Drag horizontally or use arrow keys to change separation."><ellipse cx="${c.x+shift}" cy="${c.y}" rx="${size}" ry="${size*.8}" fill="url(#im-cloud)"/><circle cx="${c.x}" cy="${c.y}" r="${c.r}" class="im-nucleus"/><text x="${c.x}" y="${c.y}" class="im-symbol">${c.symbol}</text>`;
if(game.mode==='london'){if(Math.abs(fluctuation)>.15){const left=fluctuation>0?'δ+':'δ−',right=fluctuation>0?'δ−':'δ+';s+=`<text x="${c.x-size*.76}" y="${c.y-30}" class="im-charge">${left}</text><text x="${c.x+size*.76}" y="${c.y-30}" class="im-charge">${right}</text>`;}}
else{for(const h of group.hydrogens){const dx=(h.x-c.x)/65,dy=(h.y-c.y)/65;s+=`<line x1="${c.x+dx*(c.r+1)}" y1="${c.y+dy*(c.r+1)}" x2="${h.x-dx*14}" y2="${h.y-dy*14}" class="im-bond"/><circle cx="${h.x}" cy="${h.y}" r="14" class="im-hydrogen"/><text x="${h.x}" y="${h.y}" class="im-h-symbol">H</text><text x="${h.x}" y="${h.y-23}" class="im-charge">δ+</text>`;}
s+=`<text x="${c.x}" y="${c.y-c.r-12}" class="im-charge">δ−</text>`;if(game.mode==='hydrogen')for(const a of group.lp)s+=dotPair(c.x+(c.r+10)*Math.cos(a),c.y+(c.r+10)*Math.sin(a),a+Math.PI/2);}
s+='</g>';}
for(const h of r.hydrogen){const dx=h.to.x-h.from.x,dy=h.to.y-h.from.y,len=Math.hypot(dx,dy);s+=`<line x1="${h.from.x+17*dx/len}" y1="${h.from.y+17*dy/len}" x2="${h.to.x-(h.to.r+4)*dx/len}" y2="${h.to.y-(h.to.r+4)*dy/len}" class="im-hbond"/>`;}
s+='<text x="205" y="400" class="im-side">Left particle</text><text x="615" y="400" class="im-side">Right particle</text>';$('diagram').innerHTML=s;
const amount=Math.abs(r.total);$('meter-fill').style.width=(amount*50)+'%';$('meter-fill').style.left=(r.total>=0?50:50-amount*50)+'%';$('meter-fill').classList.toggle('repulsive',r.total<0);
$('strength').textContent=r.repulsion?'Too close · strong repulsion':r.total<-.025?'Unfavourable orientation · repulsion':r.total<.025?'Very weak interaction':r.total<.35?'Weak attraction':r.total<.7?'Moderate attraction':'Strong attraction';
$('hb-state').hidden=game.mode!=='hydrogen';const hbText=r.hydrogen.length?'Hydrogen bond formed':'No hydrogen bond in this arrangement';if($('hb-state').textContent!==hbText)$('hb-state').textContent=hbText;
$('dispersion-readout').textContent='London dispersion: present';$('dipole-readout').hidden=game.mode==='london';$('dipole-readout').textContent='Permanent dipoles: '+(r.dipole>=0?'favourable orientation':'unfavourable orientation');$('hbond-readout').hidden=game.mode!=='hydrogen';$('hbond-readout').textContent='Hydrogen bonds shown: '+r.hydrogen.length;
}
function render(){for(const mode of ['london','dipole','hydrogen'])$('mode-'+mode).setAttribute('aria-pressed',String(game.mode===mode));$('gas-setting').hidden=game.mode!=='london';$('molecule-setting').hidden=game.mode!=='hydrogen';$('rotations').hidden=game.mode==='london';$('gap').value=game.gap;for(let i=0;i<2;i++){$('angle-'+i).value=game.angles[i];$('angle-value-'+i).textContent=game.angles[i]+'°';}$('pause').textContent=paused?'Resume fluctuations':'Pause fluctuations';$('pause').setAttribute('aria-pressed',String(paused));$('title').textContent=game.mode==='london'?gases[game.gas].name+' atoms':game.mode==='dipole'?'Hydrogen chloride · HCl':game.molecule.name+' · '+game.molecule.formula;renderDiagram();}
for(const mode of ['london','dipole','hydrogen'])$('mode-'+mode).addEventListener('click',()=>{game.setMode(mode);render();});
$('gas').addEventListener('change',e=>{game.gas=e.target.value;render();});$('molecule').addEventListener('change',e=>{game.species=e.target.value;game.reset();render();});$('gap').addEventListener('input',e=>{game.setGap(Number(e.target.value));render();});for(let i=0;i<2;i++)$('angle-'+i).addEventListener('input',e=>{game.rotate(i,Number(e.target.value));render();});$('reset').addEventListener('click',()=>{game.reset();render();});$('pause').addEventListener('click',()=>{paused=!paused;render();});
const svg=$('diagram'),point=e=>(e.clientX-svg.getBoundingClientRect().left)/svg.getBoundingClientRect().width*820;
svg.addEventListener('pointerdown',e=>{const p=e.target.closest('[data-particle]');if(!p||e.button!==0)return;e.preventDefault();drag={id:e.pointerId,side:Number(p.dataset.particle),x:point(e),gap:game.gap};svg.setPointerCapture(e.pointerId);});
svg.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;game.setGap(drag.gap+(point(e)-drag.x)*(drag.side?2:-2));render();});
for(const type of ['pointerup','pointercancel'])svg.addEventListener(type,e=>{if(drag&&e.pointerId===drag.id){if(svg.hasPointerCapture(e.pointerId))svg.releasePointerCapture(e.pointerId);drag=null;}});
svg.addEventListener('keydown',e=>{const p=e.target.closest('[data-particle]');if(!p||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const side=Number(p.dataset.particle);game.setGap(game.gap+(e.key==='ArrowRight'?1:-1)*(side?10:-10));render();svg.querySelector('[data-particle="'+side+'"]').focus();});
function tick(now){if(!paused&&!document.hidden&&!$('game').closest('[data-page]').hidden&&!drag&&document.activeElement?.closest('#im-diagram')==null&&now-last>70){time+=Math.min((now-last)/1000,.12);renderDiagram();last=now;}requestAnimationFrame(tick);}
if(typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches)paused=true;render();requestAnimationFrame(tick);
})();
